package com.aqua.aqualight.data.devices.light.automation

import com.aqua.aqualight.data.devices.light.automation.model.CloudFrequency as UiCloudFrequency
import com.aqua.aqualight.data.devices.light.automation.model.CloudSimulationSettings as UiCloudSimulationSettings
import com.aqua.aqualight.data.devices.light.automation.model.LightAutomationSettings as UiLightAutomationSettings
import com.aqua.aqualight.data.devices.light.automation.model.MoonlightChannel as UiMoonlightChannel
import com.aqua.aqualight.data.devices.light.automation.model.MoonlightSettings as UiMoonlightSettings
import com.aqua.aqualight.data.devices.light.curve.model.LightCurvePoint

object LightAutomationProtoMapper {
    fun toProto(settings: UiLightAutomationSettings): LightAutomationDeviceSettings { val s = sanitize(settings); return LightAutomationDeviceSettings.newBuilder().setDeviceId(s.deviceId).setOwnerUid(s.ownerUid).setMoonlight(toProtoMoonlight(s.moonlight)).setCloudSimulation(toProtoCloud(s.cloudSimulation)).setUpdatedAt(s.updatedAt).setPendingDeviceSync(s.pendingDeviceSync).build() }
    fun fromProto(proto: LightAutomationDeviceSettings): UiLightAutomationSettings = sanitize(UiLightAutomationSettings(deviceId = proto.deviceId.coerceAtLeast(0L), ownerUid = proto.ownerUid, moonlight = fromProtoMoonlight(proto.moonlight), cloudSimulation = fromProtoCloud(proto.cloudSimulation), updatedAt = proto.updatedAt.coerceAtLeast(0L), pendingDeviceSync = proto.pendingDeviceSync))
    fun sanitize(settings: UiLightAutomationSettings): UiLightAutomationSettings = settings.copy(deviceId = settings.deviceId.coerceAtLeast(0L), ownerUid = settings.ownerUid.trim(), moonlight = sanitizeMoonlight(settings.moonlight), cloudSimulation = sanitizeCloud(settings.cloudSimulation), updatedAt = settings.updatedAt.coerceAtLeast(0L))
    private fun toProtoMoonlight(settings: UiMoonlightSettings): AutomationMoonlightSettings { val s = sanitizeMoonlight(settings); return AutomationMoonlightSettings.newBuilder().setEnabled(s.enabled).setFollowProgramEnd(s.followProgramEnd).setStartTime(toProtoTimePoint(s.startTime)).setEndTime(toProtoTimePoint(s.endTime)).setChannel(toProtoMoonlightChannel(s.channel)).setIntensityPercent(s.intensityPercent).build() }
    private fun fromProtoMoonlight(settings: AutomationMoonlightSettings): UiMoonlightSettings = sanitizeMoonlight(UiMoonlightSettings(settings.enabled, settings.followProgramEnd, fromProtoTimePoint(settings.startTime), fromProtoTimePoint(settings.endTime), fromProtoMoonlightChannel(settings.channel), settings.intensityPercent))
    private fun sanitizeMoonlight(settings: UiMoonlightSettings): UiMoonlightSettings = settings.copy(startTime = sanitizeTimePoint(settings.startTime), endTime = sanitizeTimePoint(settings.endTime), intensityPercent = settings.intensityPercent.coerceIn(1, 15))
    private fun toProtoCloud(settings: UiCloudSimulationSettings): AutomationCloudSimulationSettings { val s = sanitizeCloud(settings); return AutomationCloudSimulationSettings.newBuilder().setEnabled(s.enabled).setCoveragePercent(s.coveragePercent).setFrequency(toProtoCloudFrequency(s.frequency)).build() }
    private fun fromProtoCloud(settings: AutomationCloudSimulationSettings): UiCloudSimulationSettings = sanitizeCloud(UiCloudSimulationSettings(settings.enabled, settings.coveragePercent, fromProtoCloudFrequency(settings.frequency)))
    private fun sanitizeCloud(settings: UiCloudSimulationSettings): UiCloudSimulationSettings = settings.copy(enabled = false, coveragePercent = settings.coveragePercent.coerceIn(0, 100))
    private fun toProtoTimePoint(point: LightCurvePoint): AutomationTimePoint { val p = sanitizeTimePoint(point); return AutomationTimePoint.newBuilder().setHour(p.hour).setMinute(p.minute).build() }
    private fun fromProtoTimePoint(point: AutomationTimePoint): LightCurvePoint = sanitizeTimePoint(LightCurvePoint.of(point.hour, point.minute))
    private fun sanitizeTimePoint(point: LightCurvePoint): LightCurvePoint = LightCurvePoint.of(point.hour.coerceIn(0, 23), point.minute.coerceIn(0, 59))
    private fun toProtoMoonlightChannel(channel: UiMoonlightChannel): AutomationMoonlightChannel = when (channel) { UiMoonlightChannel.BLUE -> AutomationMoonlightChannel.AUTOMATION_MOONLIGHT_CHANNEL_BLUE; UiMoonlightChannel.WHITE -> AutomationMoonlightChannel.AUTOMATION_MOONLIGHT_CHANNEL_WHITE; UiMoonlightChannel.BLUE_WHITE -> AutomationMoonlightChannel.AUTOMATION_MOONLIGHT_CHANNEL_BLUE_WHITE }
    private fun fromProtoMoonlightChannel(channel: AutomationMoonlightChannel): UiMoonlightChannel = when (channel) { AutomationMoonlightChannel.AUTOMATION_MOONLIGHT_CHANNEL_BLUE, AutomationMoonlightChannel.UNRECOGNIZED -> UiMoonlightChannel.BLUE; AutomationMoonlightChannel.AUTOMATION_MOONLIGHT_CHANNEL_WHITE -> UiMoonlightChannel.WHITE; AutomationMoonlightChannel.AUTOMATION_MOONLIGHT_CHANNEL_BLUE_WHITE -> UiMoonlightChannel.BLUE_WHITE }
    private fun toProtoCloudFrequency(frequency: UiCloudFrequency): AutomationCloudFrequency = when (frequency) { UiCloudFrequency.RARE -> AutomationCloudFrequency.AUTOMATION_CLOUD_FREQUENCY_RARE; UiCloudFrequency.NORMAL -> AutomationCloudFrequency.AUTOMATION_CLOUD_FREQUENCY_NORMAL; UiCloudFrequency.FREQUENT -> AutomationCloudFrequency.AUTOMATION_CLOUD_FREQUENCY_FREQUENT }
    private fun fromProtoCloudFrequency(frequency: AutomationCloudFrequency): UiCloudFrequency = when (frequency) { AutomationCloudFrequency.AUTOMATION_CLOUD_FREQUENCY_RARE -> UiCloudFrequency.RARE; AutomationCloudFrequency.AUTOMATION_CLOUD_FREQUENCY_NORMAL, AutomationCloudFrequency.UNRECOGNIZED -> UiCloudFrequency.NORMAL; AutomationCloudFrequency.AUTOMATION_CLOUD_FREQUENCY_FREQUENT -> UiCloudFrequency.FREQUENT }
}
